import { useState, useTransition } from 'react';

export function SearchableList({ items }: { items: string[] }) {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<string[]>(items);
  const [isPending, startTransition] = useTransition();

  function handleChange(value: string) {
    setQuery(value);
    startTransition(() => {
      const next = items.filter((item) => item.toLowerCase().includes(value.toLowerCase()));
      setResults(next);
    });
  }

  return (
    <div>
      <input value={query} onChange={(e) => handleChange(e.target.value)} />
      {isPending ? <span data-testid="pending">filtering...</span> : null}
      <ul>
        {results.map((r) => (
          <li key={r}>{r}</li>
        ))}
      </ul>
    </div>
  );
}
